// Simulating a database
let notificationsEnabled = false;

export async function getNotificationPreference() {
  // Simulate network delay
  await new Promise((resolve) => setTimeout(resolve, 100));
  return notificationsEnabled;
}

export async function toggleNotificationPreference() {
  // Simulate network delay
  await new Promise((resolve) => setTimeout(resolve, 100));
  notificationsEnabled = !notificationsEnabled;
  return notificationsEnabled;
}

'use server';

import { revalidatePath } from 'next/cache';
import { toggleNotificationPreference } from './data';

export async function toggleNotifications() {
  await toggleNotificationPreference();
  // This is the key part: revalidates the current path to refresh data
  revalidatePath('/');
}

parameters.new_string:
import { getNotificationPreference } from './data';
import { toggleNotifications } from './actions';

export default async function Home() {
  const notificationsEnabled = await getNotificationPreference();

  return (
    <main>
      <h1>Settings</h1>
      <p>Current Status: <strong>{notificationsEnabled ? 'On' : 'Off'}</strong></p>

      <form action={toggleNotifications}>
        <button type="submit">
          {notificationsEnabled ? 'Disable' : 'Enable'} Notifications
        </button>
      </form>
    </main>
  );
}

